//! Lifecycle traces generated by the pinned Quint model.
use super::itf::replay;

#[test]
fn registration_works() {
	replay::trace(include_str!("../fixtures/quint/lifecycle/registration_works.itf.json"))
		.expect("parachain lifecycle should match Quint");
}

